import{_ as n,o as a,c as t,a3 as p}from"./chunks/framework.bvEHUNtb.js";const h=JSON.parse('{"title":"07 后天八卦","description":"从《说卦传》的时间叙事进入后天八卦的方位、四时与运行结构。","frontmatter":{"title":"07 后天八卦","description":"从《说卦传》的时间叙事进入后天八卦的方位、四时与运行结构。","category":"guide","aliases":["后天八卦","文王八卦"]},"headers":[],"relativePath":"topics/traditional-wisdom/symbols/hou-tian-ba-gua.md","filePath":"topics/traditional-wisdom/symbols/hou-tian-ba-gua.md","lastUpdated":1786982540000}'),e={name:"topics/traditional-wisdom/symbols/hou-tian-ba-gua.md"};function l(i,s,c,d,o,r){return a(),t("div",null,[...s[0]||(s[0]=[p(`<h1 id="_07-·-后天八卦-宇宙的运行地图" tabindex="-1">07 · 后天八卦：宇宙的运行地图 <a class="header-anchor" href="#_07-·-后天八卦-宇宙的运行地图" aria-label="Permalink to &quot;07 · 后天八卦：宇宙的运行地图&quot;">​</a></h1><hr><h2 id="版本与引用说明" tabindex="-1">版本与引用说明 <a class="header-anchor" href="#版本与引用说明" aria-label="Permalink to &quot;版本与引用说明&quot;">​</a></h2><p>&quot;后天八卦&quot;与&quot;先天八卦&quot;一样，<strong>命名本身不见于先秦文献</strong>。<br> &quot;后天&quot;之名，同样由北宋邵雍正式提出，图式亦经朱熹《周易本义》（1177年）定型。</p><p>但后天八卦所依据的核心原文，来自《周易·说卦传》第五章——<br> 这是目前可考的最早、最直接的文献依据。</p><p>本篇同样<strong>严格区分</strong>：</p><ul><li>《说卦传》原文（先秦）</li><li>邵雍的&quot;后天学&quot;命名（北宋）</li><li>朱熹的图式定型（南宋）</li><li>后世术数应用（风水、奇门、中医等）</li></ul><hr><h2 id="一、先说位置-先天之后-后天接上" tabindex="-1">一、先说位置：先天之后，后天接上 <a class="header-anchor" href="#一、先说位置-先天之后-后天接上" aria-label="Permalink to &quot;一、先说位置：先天之后，后天接上&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>道</span></span>
<span class="line"><span> └─ 阴阳</span></span>
<span class="line"><span>      └─ 四象</span></span>
<span class="line"><span>           └─ 八卦</span></span>
<span class="line"><span>                ├─ 先天八卦（体）← 上一篇</span></span>
<span class="line"><span>                │    = 本质关系，对称结构，静态</span></span>
<span class="line"><span>                └─ 后天八卦（用）← 我们在这里</span></span>
<span class="line"><span>                     = 时空流行，运动规律，动态</span></span></code></pre></div><p>如果说先天八卦是宇宙的<strong>基因图谱</strong>（本质是什么），<br> 那后天八卦就是宇宙的<strong>运行地图</strong>（如何在时空中展开）。</p><p>两者的关系，用邵雍的话说：</p><blockquote><p>【原典】邵雍《观物外篇》，北宋，约1060年代<br> 【原文】<strong>先天之学，心也；后天之学，迹也。</strong></p></blockquote><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先天 = 心 = 内在本质，不可见</span></span>
<span class="line"><span>后天 = 迹 = 外在轨迹，可以观察、可以应用</span></span></code></pre></div><h2 id="二、原典依据-《说卦传》第五章" tabindex="-1">二、原典依据：《说卦传》第五章 <a class="header-anchor" href="#二、原典依据-《说卦传》第五章" aria-label="Permalink to &quot;二、原典依据：《说卦传》第五章&quot;">​</a></h2><blockquote><p>【原典】《周易·说卦传》第五章<br> 【时代】西周至春秋，孔子《十翼》之一<br> 【原文】<strong>帝出乎震，齐乎巽，相见乎离，致役乎坤，说言乎兑，战乎乾，劳乎坎，成言乎艮。</strong></p></blockquote><p>这是后天八卦最核心的原典。逐句拆解：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;帝出乎震&quot;</span></span>
<span class="line"><span>  帝（万物生机）从震（东方·春雷）出发。</span></span>
<span class="line"><span>  = 春天，雷声初动，万物萌发，生命开始。</span></span>
<span class="line"><span>  = 后天八卦的起点：震居正东。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;齐乎巽&quot;</span></span>
<span class="line"><span>  万物在巽（东南·风）中整齐生长。</span></span>
<span class="line"><span>  = 春末夏初，万物蓬勃，欣欣向荣。</span></span>
<span class="line"><span>  = 巽居东南。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;相见乎离&quot;</span></span>
<span class="line"><span>  万物在离（南方·火·日）中彼此显现。</span></span>
<span class="line"><span>  = 夏天，日照最强，万物盛极，光明灿烂。</span></span>
<span class="line"><span>  = 离居正南。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;致役乎坤&quot;</span></span>
<span class="line"><span>  万物在坤（西南·地）中劳作服务。</span></span>
<span class="line"><span>  = 夏末秋初，大地承载万物，收获在即。</span></span>
<span class="line"><span>  = 坤居西南。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;说言乎兑&quot;</span></span>
<span class="line"><span>  万物在兑（西方·泽·秋）中喜悦。</span></span>
<span class="line"><span>  = 秋天，收获丰盈，万物成熟，喜悦之时。</span></span>
<span class="line"><span>  = 兑居正西。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;战乎乾&quot;</span></span>
<span class="line"><span>  阴阳在乾（西北）中交战。</span></span>
<span class="line"><span>  = 秋末冬初，阴气渐盛，阳气退守，</span></span>
<span class="line"><span>    阴阳在此激烈交替。</span></span>
<span class="line"><span>  = 乾居西北。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;劳乎坎&quot;</span></span>
<span class="line"><span>  万物在坎（北方·水·冬）中劳苦潜藏。</span></span>
<span class="line"><span>  = 冬天，万物蛰伏，生命潜藏，</span></span>
<span class="line"><span>    是最艰难、最沉寂的时刻。</span></span>
<span class="line"><span>  = 坎居正北。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;成言乎艮&quot;</span></span>
<span class="line"><span>  万物在艮（东北·山）中终结与开始。</span></span>
<span class="line"><span>  = 冬末春初，旧的一年终结，新的一年孕育。</span></span>
<span class="line"><span>  = 艮居东北。艮，终也，始也。</span></span></code></pre></div><blockquote><p>⚠️ <strong>重要说明</strong>：《说卦传》第五章描述的是<strong>时间流行的过程</strong>，<br> 是一个完整的年度循环。将其对应为空间方位图，<br> 是后世易学家（尤其是邵雍）的诠释工作。<br> 原文本身，首先是一个<strong>时间叙事</strong>，其次才是方位对应。</p></blockquote><h2 id="三、-文王八卦-之名的考辨" tabindex="-1">三、&quot;文王八卦&quot;之名的考辨 <a class="header-anchor" href="#三、-文王八卦-之名的考辨" aria-label="Permalink to &quot;三、&quot;文王八卦&quot;之名的考辨&quot;">​</a></h2><p>后天八卦又常被称为&quot;文王八卦&quot;。这个名称，需要辨析。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>通行说法：后天八卦为周文王所作。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>考据现状：</span></span>
<span class="line"><span>  此说最早见于宋代文献，先秦及汉代文献</span></span>
<span class="line"><span>  均无&quot;文王作后天八卦&quot;的明确记载。</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  《说卦传》第五章本身，也没有说&quot;此为文王所作&quot;。</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  朱伯崑《易学哲学史》（北京大学出版社，1986年）指出：</span></span>
<span class="line"><span>  &quot;文王八卦&quot;之名，是宋代易学家为区分先后天</span></span>
<span class="line"><span>  而追加的命名，其历史归属尚无确凿文献支撑。</span></span></code></pre></div><p><strong>本篇的处理原则：</strong></p><p>使用&quot;后天八卦&quot;这一中性名称，不采用&quot;文王八卦&quot;的表述，以免引入未经证实的历史归属。</p><h2 id="四、后天八卦图-方位与结构" tabindex="-1">四、后天八卦图：方位与结构 <a class="header-anchor" href="#四、后天八卦图-方位与结构" aria-label="Permalink to &quot;四、后天八卦图：方位与结构&quot;">​</a></h2><blockquote><p>📌 <strong>【后天八卦方位图预留位置】</strong><br> 圆形排布：上离（南）下坎（北），左震（东）右兑（西）</p></blockquote><h3 id="标准方位-上南下北-面南而立" tabindex="-1">标准方位（上南下北，面南而立） <a class="header-anchor" href="#标准方位-上南下北-面南而立" aria-label="Permalink to &quot;标准方位（上南下北，面南而立）&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>              离（☲）南·上</span></span>
<span class="line"><span>    巽（☴）东南          坤（☷）西南</span></span>
<span class="line"><span>    震（☳）东                      兑（☱）西</span></span>
<span class="line"><span>    艮（☶）东北          乾（☰）西北</span></span>
<span class="line"><span>              坎（☵）北·下</span></span></code></pre></div><blockquote><p>⚠️ 同样是<strong>上南下北</strong>的面南视角，与先天八卦一致。<br> 但方位排布完全不同——这是最容易混淆的地方。</p></blockquote><h3 id="先天-vs-后天-方位对比" tabindex="-1">先天 vs 后天：方位对比 <a class="header-anchor" href="#先天-vs-后天-方位对比" aria-label="Permalink to &quot;先天 vs 后天：方位对比&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>卦名    先天方位    后天方位</span></span>
<span class="line"><span>─────────────────────────</span></span>
<span class="line"><span>乾      南          西北</span></span>
<span class="line"><span>坤      北          西南</span></span>
<span class="line"><span>离      东          南</span></span>
<span class="line"><span>坎      西          北</span></span>
<span class="line"><span>震      东北        东</span></span>
<span class="line"><span>巽      西南        东南</span></span>
<span class="line"><span>兑      东南        西</span></span>
<span class="line"><span>艮      西北        东北</span></span></code></pre></div><blockquote><p>除了震（东北→东）、艮（西北→东北）、巽（西南→东南）、兑（东南→西）之外，乾坤坎离四正卦的方位<strong>全部改变</strong>。<br> 先天乾南，后天乾西北；先天坎西，后天坎北——这不是笔误，是两套体系本来就不同。</p></blockquote><hr><h2 id="五、后天八卦与五行、四时的完整对应" tabindex="-1">五、后天八卦与五行、四时的完整对应 <a class="header-anchor" href="#五、后天八卦与五行、四时的完整对应" aria-label="Permalink to &quot;五、后天八卦与五行、四时的完整对应&quot;">​</a></h2><p>这是后天八卦最重要的应用基础。</p><table tabindex="0"><thead><tr><th style="text-align:center;">卦名</th><th style="text-align:center;">符号</th><th style="text-align:center;">方位</th><th style="text-align:center;">五行</th><th style="text-align:center;">四时</th><th style="text-align:center;">节气区间</th><th style="text-align:center;">九宫数</th></tr></thead><tbody><tr><td style="text-align:center;">震</td><td style="text-align:center;">☳</td><td style="text-align:center;">正东</td><td style="text-align:center;">木</td><td style="text-align:center;">春</td><td style="text-align:center;">春分前后</td><td style="text-align:center;">3</td></tr><tr><td style="text-align:center;">巽</td><td style="text-align:center;">☴</td><td style="text-align:center;">东南</td><td style="text-align:center;">木</td><td style="text-align:center;">春末</td><td style="text-align:center;">立夏前后</td><td style="text-align:center;">4</td></tr><tr><td style="text-align:center;">离</td><td style="text-align:center;">☲</td><td style="text-align:center;">正南</td><td style="text-align:center;">火</td><td style="text-align:center;">夏</td><td style="text-align:center;">夏至前后</td><td style="text-align:center;">9</td></tr><tr><td style="text-align:center;">坤</td><td style="text-align:center;">☷</td><td style="text-align:center;">西南</td><td style="text-align:center;">土</td><td style="text-align:center;">长夏</td><td style="text-align:center;">立秋前后</td><td style="text-align:center;">2</td></tr><tr><td style="text-align:center;">兑</td><td style="text-align:center;">☱</td><td style="text-align:center;">正西</td><td style="text-align:center;">金</td><td style="text-align:center;">秋</td><td style="text-align:center;">秋分前后</td><td style="text-align:center;">7</td></tr><tr><td style="text-align:center;">乾</td><td style="text-align:center;">☰</td><td style="text-align:center;">西北</td><td style="text-align:center;">金</td><td style="text-align:center;">秋末</td><td style="text-align:center;">立冬前后</td><td style="text-align:center;">6</td></tr><tr><td style="text-align:center;">坎</td><td style="text-align:center;">☵</td><td style="text-align:center;">正北</td><td style="text-align:center;">水</td><td style="text-align:center;">冬</td><td style="text-align:center;">冬至前后</td><td style="text-align:center;">1</td></tr><tr><td style="text-align:center;">艮</td><td style="text-align:center;">☶</td><td style="text-align:center;">东北</td><td style="text-align:center;">土</td><td style="text-align:center;">冬末</td><td style="text-align:center;">立春前后</td><td style="text-align:center;">8</td></tr><tr><td style="text-align:center;">（中）</td><td style="text-align:center;">—</td><td style="text-align:center;">中央</td><td style="text-align:center;">土</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">5</td></tr></tbody></table><blockquote><p>【原典依据】</p><ul><li>方位与四时：《周易·说卦传》第五章</li><li>五行对应：《礼记·月令》、《黄帝内经·素问·阴阳应象大论》</li><li>九宫数：《黄帝内经·灵枢·九宫八风》（战国至西汉）</li></ul></blockquote><hr><h2 id="六、九宫数-洛书与后天八卦的叠合" tabindex="-1">六、九宫数：洛书与后天八卦的叠合 <a class="header-anchor" href="#六、九宫数-洛书与后天八卦的叠合" aria-label="Permalink to &quot;六、九宫数：洛书与后天八卦的叠合&quot;">​</a></h2><p>后天八卦的方位，与洛书九宫数完全对应：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        4  9  2</span></span>
<span class="line"><span>        3  5  7</span></span>
<span class="line"><span>        8  1  6</span></span>
<span class="line"><span></span></span>
<span class="line"><span>对应方位（上南下北）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        巽4  离9  坤2</span></span>
<span class="line"><span>        震3  中5  兑7</span></span>
<span class="line"><span>        艮8  坎1  乾6</span></span></code></pre></div><blockquote><p>【原典】《黄帝内经·灵枢·九宫八风》<br> 【原文】<strong>&quot;太一常以冬至之日，居叶蛰之宫四十六日……&quot;</strong><br> （九宫方位与八卦、八风的对应，此篇有完整描述）</p></blockquote><p><strong>洛书幻方验证：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任意一行、一列、对角线之和 = 15</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  4+9+2 = 15  ✓</span></span>
<span class="line"><span>  3+5+7 = 15  ✓</span></span>
<span class="line"><span>  8+1+6 = 15  ✓</span></span>
<span class="line"><span>  4+3+8 = 15  ✓</span></span>
<span class="line"><span>  9+5+1 = 15  ✓</span></span>
<span class="line"><span>  2+7+6 = 15  ✓</span></span>
<span class="line"><span>  4+5+6 = 15  ✓（对角）</span></span>
<span class="line"><span>  2+5+8 = 15  ✓（对角）</span></span></code></pre></div><blockquote><p>后天八卦 + 洛书九宫 = 一套完整的时空坐标系。<br> 这个叠合，是后世风水、奇门遁甲、紫微斗数等术数体系的共同数理基础。</p></blockquote><h2 id="七、后天八卦的运动规律-顺时针流行" tabindex="-1">七、后天八卦的运动规律：顺时针流行 <a class="header-anchor" href="#七、后天八卦的运动规律-顺时针流行" aria-label="Permalink to &quot;七、后天八卦的运动规律：顺时针流行&quot;">​</a></h2><p>先天八卦是对称的、静态的；<br> 后天八卦是流动的、循环的。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>后天八卦的运行方向：顺时针</span></span>
<span class="line"><span></span></span>
<span class="line"><span>震（东·春）</span></span>
<span class="line"><span>  → 巽（东南·春末）</span></span>
<span class="line"><span>    → 离（南·夏）</span></span>
<span class="line"><span>      → 坤（西南·长夏）</span></span>
<span class="line"><span>        → 兑（西·秋）</span></span>
<span class="line"><span>          → 乾（西北·秋末）</span></span>
<span class="line"><span>            → 坎（北·冬）</span></span>
<span class="line"><span>              → 艮（东北·冬末）</span></span>
<span class="line"><span>                → 震（东·春）……</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 一个完整的年度循环，周而复始。</span></span></code></pre></div><p>这个循环，对应的是：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阳气：冬至（坎·北）开始生发</span></span>
<span class="line"><span>      → 春分（震·东）阳气旺盛</span></span>
<span class="line"><span>      → 夏至（离·南）阳气极盛</span></span>
<span class="line"><span>      → 秋分（兑·西）阳气收敛</span></span>
<span class="line"><span>      → 冬至（坎·北）阳气潜藏</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 一年四季，阴阳消长的完整轨迹。</span></span></code></pre></div><h2 id="八、先天与后天的核心差异" tabindex="-1">八、先天与后天的核心差异 <a class="header-anchor" href="#八、先天与后天的核心差异" aria-label="Permalink to &quot;八、先天与后天的核心差异&quot;">​</a></h2><p>这是理解两套体系最关键的一步。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先天八卦                    后天八卦</span></span>
<span class="line"><span>────────────────────────────────────────────</span></span>
<span class="line"><span>体                          用</span></span>
<span class="line"><span>本质关系                    时空流行</span></span>
<span class="line"><span>对称结构                    循环运动</span></span>
<span class="line"><span>静态                        动态</span></span>
<span class="line"><span>乾南·坤北（天地定位）       离南·坎北（日月运行）</span></span>
<span class="line"><span>《说卦传》第三章            《说卦传》第五章</span></span>
<span class="line"><span>宇宙&quot;是什么&quot;               宇宙&quot;怎么动&quot;</span></span></code></pre></div><p><strong>一个关键的哲学转换：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>先天：乾（天）在南，坤（地）在北</span></span>
<span class="line"><span>      = 天在上，地在下，这是本体的位置</span></span>
<span class="line"><span></span></span>
<span class="line"><span>后天：离（火·日）在南，坎（水·月）在北</span></span>
<span class="line"><span>      = 太阳在南方最高处，水在北方潜藏</span></span>
<span class="line"><span>      = 这是现象界的实际运行</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先天讲的是&quot;天地&quot;，后天讲的是&quot;日月&quot;。</span></span>
<span class="line"><span>天地是本体，日月是现象。体用之别，在此最为清晰。</span></span></code></pre></div><blockquote><p>朱伯崑《易学哲学史》（北京大学出版社，1986年）指出：<br> 先天后天之分，是宋代易学最重要的理论建构之一，<br> 其核心是将《易》的体用关系系统化，<br> 为后世象数易学提供了完整的理论框架。</p></blockquote><h2 id="九、后天八卦的三大应用领域" tabindex="-1">九、后天八卦的三大应用领域 <a class="header-anchor" href="#九、后天八卦的三大应用领域" aria-label="Permalink to &quot;九、后天八卦的三大应用领域&quot;">​</a></h2><p>后天八卦之所以比先天八卦更常见于日常应用，<br> 原因很简单：<strong>它是动态的，可以对应时间和空间的变化。</strong></p><p><strong>① 中医：脏腑与方位</strong></p><p>【原典】《黄帝内经·素问·阴阳应象大论》</p><ul><li>东方·木·肝</li><li>南方·火·心</li><li>中央·土·脾</li><li>西方·金·肺</li><li>北方·水·肾</li></ul><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>后天八卦方位 + 五行 = 中医五脏定位的空间依据</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  震·巽（东·东南）= 木 = 肝·胆</span></span>
<span class="line"><span>  离（南）         = 火 = 心·小肠</span></span>
<span class="line"><span>  坤·艮（西南·东北）= 土 = 脾·胃</span></span>
<span class="line"><span>  兑·乾（西·西北） = 金 = 肺·大肠</span></span>
<span class="line"><span>  坎（北）         = 水 = 肾·膀胱</span></span></code></pre></div><p><strong>② 风水：九宫飞星的起点</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>后天八卦九宫方位，是玄空风水&quot;飞星盘&quot;的静盘基础。</span></span>
<span class="line"><span>一白坎·二黑坤·三碧震·四绿巽·</span></span>
<span class="line"><span>五黄中·六白乾·七赤兑·八白艮·九紫离</span></span>
<span class="line"><span></span></span>
<span class="line"><span>（九星颜色为星宿本命色，非五行本色——</span></span>
<span class="line"><span> 详见上一篇&quot;九星颜色体系&quot;的辨析）</span></span></code></pre></div><p><strong>③ 奇门遁甲：时空推演的坐标</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>奇门遁甲以后天八卦九宫为基础坐标，</span></span>
<span class="line"><span>将时间（时辰·日·月·年）与空间（九宫方位）</span></span>
<span class="line"><span>叠合推演，是古代最复杂的时空推算体系之一。</span></span></code></pre></div><h2 id="十、一个常见误区的澄清" tabindex="-1">十、一个常见误区的澄清 <a class="header-anchor" href="#十、一个常见误区的澄清" aria-label="Permalink to &quot;十、一个常见误区的澄清&quot;">​</a></h2><blockquote><p><strong>误区：先天八卦和后天八卦，哪个&quot;更正确&quot;？</strong></p></blockquote><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这个问题，本身就问错了。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先天八卦 = 描述本质关系的工具</span></span>
<span class="line"><span>后天八卦 = 描述时空运行的工具</span></span>
<span class="line"><span></span></span>
<span class="line"><span>就像问&quot;地图和地球仪，哪个更正确？&quot;——</span></span>
<span class="line"><span>两者描述的是不同维度的信息，</span></span>
<span class="line"><span>不存在谁取代谁的问题。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>正确的用法：</span></span>
<span class="line"><span>  谈宇宙的本质结构 → 用先天八卦</span></span>
<span class="line"><span>  谈时间、方位、运动 → 用后天八卦</span></span>
<span class="line"><span>  谈中医、风水、奇门 → 用后天八卦</span></span>
<span class="line"><span>  两者混用 → 错误</span></span></code></pre></div><hr><h2 id="十一、本章小结" tabindex="-1">十一、本章小结 <a class="header-anchor" href="#十一、本章小结" aria-label="Permalink to &quot;十一、本章小结&quot;">​</a></h2><p>后天八卦，说了一件事：</p><blockquote><p><strong>宇宙在时空中，是一个周而复始的循环。</strong></p></blockquote><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 有起点，有终点，终点即起点</span></span>
<span class="line"><span>   震（春·东）出发，艮（冬末·东北）终结，</span></span>
<span class="line"><span>   终结之后，又回到震——</span></span>
<span class="line"><span>   这不是直线，是圆。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 每个位置，都有其时间含义</span></span>
<span class="line"><span>   不只是空间方位，更是时间节点。</span></span>
<span class="line"><span>   后天八卦，是把时间画在了空间里。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>③ 阴阳消长，有迹可循</span></span>
<span class="line"><span>   从坎（冬·水·阳气最弱）到离（夏·火·阳气最盛），</span></span>
<span class="line"><span>   再从离回到坎——</span></span>
<span class="line"><span>   这个循环，是可以观察、可以推算、可以应用的。</span></span></code></pre></div><p>最后说一句实在话：</p><p>先天八卦告诉你宇宙的结构，后天八卦告诉你宇宙的节奏。</p><p>结构是不变的，节奏是流动的。两张图合在一起，才是完整的宇宙观。</p><p>帝出乎震——每一年的春天，雷声第一次响起的那一刻，都是这个循环重新开始的证明。</p><h2 id="附录-引用索引" tabindex="-1">附录：引用索引 <a class="header-anchor" href="#附录-引用索引" aria-label="Permalink to &quot;附录：引用索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">引用内容</th><th style="text-align:left;">原典／来源</th><th style="text-align:left;">时代／年份</th></tr></thead><tbody><tr><td style="text-align:left;">&quot;帝出乎震，齐乎巽……&quot;</td><td style="text-align:left;">《周易·说卦传》第五章</td><td style="text-align:left;">西周至春秋</td></tr><tr><td style="text-align:left;">&quot;先天之学，心也；后天之学，迹也&quot;</td><td style="text-align:left;">邵雍《观物外篇》</td><td style="text-align:left;">北宋，约1060年代</td></tr><tr><td style="text-align:left;">后天八卦图式定型</td><td style="text-align:left;">朱熹《周易本义》</td><td style="text-align:left;">南宋，1177年</td></tr><tr><td style="text-align:left;">九宫八风与后天八卦方位</td><td style="text-align:left;">《黄帝内经·灵枢·九宫八风》</td><td style="text-align:left;">战国至西汉</td></tr><tr><td style="text-align:left;">五行五方与五脏对应</td><td style="text-align:left;">《黄帝内经·素问·阴阳应象大论》</td><td style="text-align:left;">战国至西汉</td></tr><tr><td style="text-align:left;">五行四时方位</td><td style="text-align:left;">《礼记·月令》</td><td style="text-align:left;">战国至西汉</td></tr><tr><td style="text-align:left;">&quot;文王八卦&quot;命名考辨</td><td style="text-align:left;">朱伯崑《易学哲学史》</td><td style="text-align:left;">北京大学出版社，1986年</td></tr><tr><td style="text-align:left;">先天后天体用理论框架</td><td style="text-align:left;">朱伯崑《易学哲学史》</td><td style="text-align:left;">北京大学出版社，1986年</td></tr><tr><td style="text-align:left;">后天八卦与《说卦传》诠释</td><td style="text-align:left;">廖名春《周易经传与易学史新论》</td><td style="text-align:left;">齐鲁书社，2001年</td></tr><tr><td style="text-align:left;">后天八卦在中医中的应用</td><td style="text-align:left;">王鸿等《后天八卦在黄帝内经中的应用》</td><td style="text-align:left;">北京中医药大学学报，2020年</td></tr></tbody></table><hr><p><em>文档版本：v1.0 · 后天八卦 ｜ 2026年7月 ｜ 持续更新中</em></p>`,82)])])}const u=n(e,[["render",l]]);export{h as __pageData,u as default};
